    private const val BUILTIN_FALLBACK_OR_KEY = "c2stb3ItdjEtM2U1M2U2YmViZTc2M2ZiOGZjYzE3M2NmMjg0NzFjNjM5MDJjZGZjZWEyMGNlMjhmYmY1ODdiZWRiNDgzM2YwMw=="

    /**
     * Resolves the active AI API key (custom user key, build configuration, or built-in fallback).
     */
    fun resolveApiKey(context: Context): String {
        val prefs = context.getSharedPreferences("adshield_prefs", Context.MODE_PRIVATE)
        val customKey = prefs.getString("fokk_ai_api_key", "")?.trim().orEmpty()
        if (customKey.isNotBlank()) return customKey

        if (BuildConfig.FOKK_AI_KEY.isNotBlank()) return BuildConfig.FOKK_AI_KEY

        return try {
            String(Base64.decode(BUILTIN_FALLBACK_OR_KEY, Base64.DEFAULT), StandardCharsets.UTF_8).trim()
        } catch (_: Exception) {
            ""
        }
    }

    /**
     * Cleans chain-of-thought scratchpad notes, think blocks, and emojis from LLM output.
     */
    fun sanitizeLlmOutput(raw: String): String {
        if (raw.isBlank()) return ""
        var s = raw.replace(Regex("(?s)<think>.*?</think>"), "")
        s = s.replace(Regex("(?is)^(\\*\\*)?thinking process:?(\\*\\*)?.*?\n\n"), "")
        s = s.replace(Regex("(?is)^(\\*\\*)?here('s| is) a thinking process:?(\\*\\*)?.*?\n\n"), "")
        s = s.replace(Regex("(?is)^we need (to )?answer as fokk ai.*?(\n\n|$)"), "")
        s = s.replace(Regex("(?is)^okay, let('s| us) analyze.*?(\n\n|$)"), "")
        s = s.replace(Regex("(?is)^let's think step by step.*?(\n\n|$)"), "")
        return stripEmojis(s).trim()
    }

    /**
     * Generates a comprehensive multi-source forensic intelligence brief for a webpage.
     */
    suspend fun analyzeWebpage(
        context: Context,
        pageTitle: String,
        pageHost: String,
        pageUrl: String,
        pageContext: String,
        externalSources: List<CorroboratedSource>
    ): FokkAiAnalysis = withContext(Dispatchers.IO) {
        val apiKey = resolveApiKey(context)

        val systemPrompt = buildString {
            append("You are Fokk AI, an objective, high-intelligence Truth and Research Intelligence Engine embedded in Fokk Browser.\n")
            append("Your methodology is forensic verification, cross-examination against independent reporting, and neutral empirical synthesis.\n\n")
            append("ARTICLE INFORMATION:\n")
            append("Domain: $pageHost\n")
            append("Title: $pageTitle\n")
            append("URL: $pageUrl\n\n")

            if (externalSources.isNotEmpty()) {
                append("CORROBORATED MULTI-SOURCE WEB INTEL:\n")
                externalSources.forEachIndexed { i, s ->
                    append("[Source ${i + 1}] (${s.sourceType}) ${s.title} | ${s.domain} (${s.url})\n")
                    if (s.snippet.isNotBlank()) append("   Summary: ${s.snippet}\n")
                    if (s.timestamp.isNotBlank()) append("   Date: ${s.timestamp}\n")
                }
                append("\n")
            }

            append("TASK INSTRUCTIONS:\n")
            append("Deliver authoritative, sharp, direct analysis. Do NOT output any internal thinking steps, chain-of-thought, or meta-commentary.\n")
            append("- Distinguish between the original reporting newsroom (e.g. Sky Sports, The Athletic) and secondary social aggregators (e.g. Twitter/X handles).\n")
            append("- Use tiered, trustworthy verdicts: Officially Confirmed / Credibly Reported, Not Yet Official / Single-Source Reporting / Unconfirmed Report.\n")
            append("- Avoid buzzwords like 'Forensic Consensus' or 'Verified Record'. Use plain, honest phrasing.\n")
            append("Format your exact output with these headers:\n\n")
            append("EXECUTIVE_BRIEF:\n")
            append("[2-3 authoritative sentences directly stating whether the claim is real, what reputable outlets report, and whether official confirmation exists]\n\n")
            append("KEY_EVIDENCE:\n")
            append("- [Verifiable key fact 1]\n")
            append("- [Verifiable key fact 2]\n")
            append("- [Verifiable key fact 3]\n\n")
            append("TRUTH_AUDIT:\n")
            append("SCORE: [Integer 0 to 100 representing credibility]\n")
            append("VERDICT: [Tiered verdict: Officially Confirmed / Credibly Reported, Not Yet Official / Single-Source / Unconfirmed]\n")
            append("BIAS: [Neutral / Fact-Focused, Analytical Commentary, etc.]\n")
            append("LAYER1_DOMAIN: [Page authenticity and distribution channel audit - distinguish host platform from original reporters]\n")
            append("LAYER2_STANCE: [Rhetorical stance audit - tone, sensationalism, and reporting framework]\n")
            append("LAYER3_EVIDENCE: [Evidence density and independent cross-corroboration depth]\n\n")
            append("SUGGESTED_FOLLOWUPS:\n")
            append("[Claim-specific question 1] | [Claim-specific question 2]\n\n")
            append("Strictly ZERO emojis anywhere. Start directly with EXECUTIVE_BRIEF: without conversational filler.")
        }

        val userQuery = if (pageContext.isNotBlank()) {
            "Analyze and verify the key claims in this article based on independent evidence:\n\n${pageContext.take(9000)}"
        } else {
            "Analyze and verify this topic: '$pageTitle' from $pageHost based on multi-source reporting."
        }

        val rawAnswer = queryInferencePipeline(apiKey, systemPrompt, userQuery)

        if (rawAnswer.isNotBlank()) {
            parseAnalysisOutput(rawAnswer, externalSources, pageTitle, pageHost)
        } else {
            // Intelligent on-device synthesis fallback
            synthesizeOfflineAnalysis(pageTitle, pageHost, pageContext, externalSources)
        }
    }

    /**
     * Executes an interactive research query with multi-source grounding.
     */
    suspend fun queryInteractiveResearch(
        context: Context,
        userQuery: String,
        pageTitle: String,
        pageHost: String,
        pageContext: String,
        externalSources: List<CorroboratedSource>
    ): Pair<String, List<String>> = withContext(Dispatchers.IO) {
        val apiKey = resolveApiKey(context)

        val systemPrompt = buildString {
            append("You are Fokk AI, an objective, advanced research assistant embedded in Fokk Browser, powered by multi-source truth synthesis.\n")
            if (pageHost.isNotBlank() && pageTitle.isNotBlank()) {
                append("Current Page: '$pageTitle' ($pageHost)\n\n")
            }
            if (pageContext.isNotBlank()) {
                append("Page Context:\n${pageContext.take(7000)}\n\n")
            }
            if (externalSources.isNotEmpty()) {
                append("Corroborated Web Search Sources:\n")
                externalSources.forEachIndexed { i, s ->
                    append("[${i + 1}] ${s.title} | ${s.domain} | ${s.url}\n")
                    if (s.snippet.isNotBlank()) append("   ${s.snippet}\n")
                }
                append("\n")
            }
            append("INSTRUCTIONS:\n")
            append("- Open with an immediate, plain-spoken direct answer to the user's question, stating whether the claim or event is confirmed, credibly reported, or unverified.\n")
            append("- Synthesize what established newsrooms specifically report, citing key facts, dates, court findings, or official statements.\n")
            append("- If external corroborating sources are provided, cite them using inline brackets [1], [2].\n")
            append("- Clearly distinguish primary newsroom journalism from secondhand social aggregation.\n")
            append("- Answer the question objectively, concisely, and cleanly. Avoid buzzwords.\n")
            append("- Strictly NO emojis anywhere in the response. Output clean professional markdown.\n")
            append("- At the very end of your response, output on a new line: SUGGESTED_FOLLOWUPS: then 2 relevant follow-up research questions separated by | character.")
        }

        val rawAnswer = queryInferencePipeline(apiKey, systemPrompt, userQuery)
        val cleanAnswer = if (rawAnswer.isNotBlank()) {
            sanitizeLlmOutput(rawAnswer)
        } else {
            buildOfflineForensicSynthesis(userQuery, pageContext, externalSources)
        }

        val followUpSplit = cleanAnswer.split(Regex("(?i)SUGGESTED_FOLLOWUPS:"))
        val answerText = followUpSplit[0].trimEnd()
        val followUps = if (followUpSplit.size > 1) {
            followUpSplit[1].trim().split(Regex("[|\n]"))
                .map { stripEmojis(it.trim().removePrefix("-").removePrefix("*").trim()) }
                .filter { it.isNotBlank() && it.length > 5 }
                .take(3)
        } else {
            listOf(
                "What are the verified primary sources for this topic?",
                "How do other major independent outlets report on this issue?"
            )
        }

        Pair(answerText, followUps)
    }

    /**
     * Tries available API endpoints with failover.
     */
    private fun queryInferencePipeline(apiKey: String, systemPrompt: String, userQuery: String): String {
        if (apiKey.isBlank()) return ""

        // If user provided a Google Gemini API key (starts with AIza)
        if (apiKey.startsWith("AIza", ignoreCase = true)) {
            val geminiResp = callGeminiDirectApi(apiKey, systemPrompt, userQuery)
            if (geminiResp.isNotBlank()) return geminiResp
        }

        // OpenRouter inference with modern instruct models
        for (model in FAILOVER_MODELS) {
            val resp = callOpenRouterEndpoint(apiKey, systemPrompt, userQuery, model)
            if (resp.isNotBlank()) return resp
        }

        return ""
    }

    /**
     * Direct call to Google Gemini Flash API.
     */
    private fun callGeminiDirectApi(apiKey: String, systemPrompt: String, userQuery: String): String {
        return try {
            val endpoint = "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=$apiKey"
            val combinedPrompt = "$systemPrompt\n\nUSER QUERY:\n$userQuery"

            val body = JSONObject().apply {
                put("contents", JSONArray().apply {
                    put(JSONObject().apply {
                        put("parts", JSONArray().apply {
                            put(JSONObject().apply {
                                put("text", combinedPrompt)
                            })
                        })
                    })
                })
                put("generationConfig", JSONObject().apply {
                    put("temperature", 0.3)
                    put("maxOutputTokens", 1200)
                })
            }.toString().toByteArray(StandardCharsets.UTF_8)

            val conn = (URL(endpoint).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                setRequestProperty("Content-Type", "application/json")
                connectTimeout = DEFAULT_CONNECT_TIMEOUT
                readTimeout = DEFAULT_READ_TIMEOUT
                doOutput = true
            }

            conn.outputStream.use { it.write(body) }

            if (conn.responseCode == HttpURLConnection.HTTP_OK) {
                val resp = conn.inputStream.bufferedReader(StandardCharsets.UTF_8).use { it.readText() }
                val root = JSONObject(resp)
                val candidates = root.optJSONArray("candidates") ?: return ""
                if (candidates.length() == 0) return ""
                val parts = candidates.getJSONObject(0).optJSONObject("content")?.optJSONArray("parts") ?: return ""
                if (parts.length() == 0) return ""
                val text = parts.getJSONObject(0).optString("text", "")
                sanitizeLlmOutput(text)
            } else {
                ""
            }
        } catch (_: Exception) {
            ""
        }
    }

    /**
     * Queries OpenRouter chat completions endpoint.
     */
    private fun callOpenRouterEndpoint(
        apiKey: String,
        systemPrompt: String,
        userQuery: String,
        model: String
    ): String {
        return try {
            val endpoint = "https://openrouter.ai/api/v1/chat/completions"
            val body = JSONObject().apply {
                put("model", model)
                put("max_tokens", 1000)
                put("temperature", 0.3)
                put("messages", JSONArray().apply {
                    put(JSONObject().apply {
                        put("role", "system")
                        put("content", systemPrompt)
                    })
                    put(JSONObject().apply {
                        put("role", "user")
                        put("content", userQuery)
                    })
                })
            }.toString().toByteArray(StandardCharsets.UTF_8)

            val conn = (URL(endpoint).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                setRequestProperty("Content-Type", "application/json")
                if (apiKey.isNotBlank()) {
                    setRequestProperty("Authorization", "Bearer $apiKey")
                }
                setRequestProperty("HTTP-Referer", "https://fokk.app")
                setRequestProperty("X-Title", "Fokk Browser AI")
                connectTimeout = DEFAULT_CONNECT_TIMEOUT
                readTimeout = DEFAULT_READ_TIMEOUT
                doOutput = true
            }

            conn.outputStream.use { it.write(body) }

            if (conn.responseCode == HttpURLConnection.HTTP_OK) {
                val resp = conn.inputStream.bufferedReader(StandardCharsets.UTF_8).use { it.readText() }
                val json = JSONObject(resp)
                val choices = json.optJSONArray("choices") ?: return ""
                if (choices.length() == 0) return ""
                val message = choices.getJSONObject(0).optJSONObject("message") ?: return ""

                // Only consume the final generated content - never leak reasoning scratchpad
                val text = message.optString("content", "").trim()
                if (text.isBlank() || text == "null") {
                    ""
                } else {
                    sanitizeLlmOutput(text)
                }
            } else {
                ""
            }
        } catch (_: Exception) {
            ""
        }
    }

    data class CredibilityAssessment(
        val score: Int,
        val verdict: String,
        val reason: String,
        val isAggregator: Boolean,
        val originalSource: String,
        val aggregatorSource: String = "",
        val layer1: String,
        val layer2: String,
        val layer3: String,
        val whatsMissing: String = ""
    )

    /**
     * Categorizes a bullet point into FACT, CLAIM, or OPINION.
     */
    fun classifyBullet(text: String): String {
        val t = text.lowercase(Locale.ROOT)
        // Hard factual markers: legal rulings, sentences, arrests, dates, confirmed numbers, institutional actions
        val hasFactualMarkers = Regex("""\b(?:jailed|sentenced|arrested|convicted|pleaded|announced|confirmed|published|appointed|died|founded|ruled|voted|signed|acquired|passed|established|20\d{2}|\$\d+|\d+k|\d+m|\d+b|\d+\s*(?:years?|months?|days?)|ten-and-a-half|years earlier)\b""").containsMatchIn(t)
        // Subjective opinion markers
        val hasOpinionKeywords = Regex("""\b(?:impressive|masterclass|disaster|amazing|incredible|appalling|shocking|disgraceful|outrageous|arguably|perhaps|believe|fans|pundit|opinion|feels|seems|beautiful|awful|terrible)\b""").containsMatchIn(t)
        // Claim / quote / allegation markers
        val hasClaimKeywords = Regex("""\b(?:claims?|claimed|alleged|allegations?|verbally agreed|in talks|rumored|sources say|according to|set to|disputed|unconfirmed)\b""").containsMatchIn(t)

        return when {
            hasOpinionKeywords -> "OPINION"
            hasFactualMarkers && !hasClaimKeywords -> "FACT"
            hasClaimKeywords -> "CLAIM"
            hasFactualMarkers -> "FACT"
            else -> "CLAIM"
        }
    }

    /**
     * Single deterministic credibility assessment formula.
     * Produces one unified score, a tiered verdict, and a visible rationale.
     */
    fun evaluateCredibility(
        host: String,
        title: String,
        context: String,
        sources: List<CorroboratedSource>,
        tagScore: Int? = null,
        tagVerdict: String = ""
    ): CredibilityAssessment {
        val normHost = host.lowercase(Locale.ROOT).removePrefix("www.")
        val isSocialAggregator = normHost.contains("x.com") || normHost.contains("twitter.com") ||
                normHost.contains("reddit.com") || normHost.contains("threads.net") || normHost.contains("bsky.app")

        val combinedText = "$title $context".lowercase(Locale.ROOT)

        // Identify cited primary source ONLY when actually attributing or on an aggregator platform
        val explicitAttribution = Regex("""(?i)(?:first reported by|according to|citing|reported by|as told to|per)\s+([A-Z][a-zA-Z\s]{2,25})""").find("$title $context")
        val citedOutletName = explicitAttribution?.groupValues?.get(1)?.trim().orEmpty()

        val detectedOriginalSource = when {
            citedOutletName.contains("Sky", ignoreCase = true) -> "Sky News"
            citedOutletName.contains("Athletic", ignoreCase = true) -> "The Athletic"
            citedOutletName.contains("Guardian", ignoreCase = true) -> "The Guardian"
            citedOutletName.contains("BBC", ignoreCase = true) -> "BBC News"
            citedOutletName.contains("Times", ignoreCase = true) -> "The Times"
            citedOutletName.contains("Independent", ignoreCase = true) -> "The Independent"
            citedOutletName.contains("Standard", ignoreCase = true) -> "The Standard"
            citedOutletName.contains("Reuters", ignoreCase = true) -> "Reuters"
            citedOutletName.isNotBlank() -> citedOutletName
            isSocialAggregator && combinedText.contains("sky sports") -> "Sky Sports"
            isSocialAggregator && combinedText.contains("sky news") -> "Sky News"
            isSocialAggregator && combinedText.contains("bbc") -> "BBC News"
            isSocialAggregator && combinedText.contains("the athletic") -> "The Athletic"
            isSocialAggregator && combinedText.contains("guardian") -> "The Guardian"
            isSocialAggregator && combinedText.contains("the times") -> "The Times"
            isSocialAggregator && combinedText.contains("independent") -> "The Independent"
            isSocialAggregator && combinedText.contains("reuters") -> "Reuters"
            else -> ""
        }

        val aggregatorSource = when {
            normHost.contains("x.com") || normHost.contains("twitter.com") -> "X.com / Social Feed"
            normHost.contains("reddit.com") -> "Reddit Post"
            normHost.contains("youtube.com") || normHost == "youtu.be" -> "YouTube Video"
            isSocialAggregator -> "Social Aggregator"
            else -> ""
        }

        val isOfficialAnnouncement = combinedText.contains("official statement") ||
                combinedText.contains("press release") ||
                combinedText.contains("sec filing") ||
                combinedText.contains("court ruling") ||
                combinedText.contains("official announcement") ||
                combinedText.contains("sentenced to") ||
                combinedText.contains("ministry of justice") ||
                combinedText.contains("prison service confirmed")

        val newsSourcesCount = sources.count { s ->
            s.sourceType == "NEWS" ||
            s.domain.contains("times") || s.domain.contains("guardian") ||
            s.domain.contains("bbc") || s.domain.contains("reuters") ||
            s.domain.contains("standard") || s.domain.contains("athletic") ||
            s.domain.contains("independent") || s.domain.contains("lbc") ||
            s.domain.contains("telegraph")
        }

        val (score, verdict, reason) = when {
            isOfficialAnnouncement -> {
                Triple(
                    95,
                    "Officially Confirmed",
                    "Direct institutional announcement, court ruling, or confirmed public record."
                )
            }
            sources.size >= 4 || newsSourcesCount >= 3 -> {
                val s = minOf(92, 85 + minOf(sources.size, 6))
                Triple(
                    s,
                    "Credibly Reported Across Multiple Outlets",
                    "Corroborated across ${sources.size} independent newsrooms; consistent reporting across major outlets."
                )
            }
            sources.size in 1..3 -> {
                Triple(
                    76,
                    "Single-Source / Limited Corroboration",
                    "Reported by limited newsrooms; awaiting broader independent verification."
                )
            }
            isSocialAggregator -> {
                Triple(
                    45,
                    "Unconfirmed Social Media Post",
                    "Secondhand social media distribution; unverified without primary newsroom reporting."
                )
            }
            else -> {
                Triple(
                    70,
                    "Direct Editorial Reporting",
                    "Published directly by $host; awaiting secondary independent verification."
                )
            }
        }

        // Layer 1: Page Authenticity & Distribution Channel (NOT claim veracity)
        val l1 = if (isSocialAggregator) {
            val orig = if (detectedOriginalSource.isNotBlank()) " citing $detectedOriginalSource" else ""
            "Page Authenticity: Verified transport (TLS) on $host. Note: This post is secondhand social distribution$orig, not a primary newsroom."
        } else {
            "Page Authenticity: Verified direct origin ($host). Secure TLS session with registered editorial domain."
        }

        // Layer 2: Rhetorical Stance & Framing (with concrete loaded words analysis)
        val loadedWords = listOf("bombshell", "shock move", "masterclass", "disaster", "embarrassing", "furious", "unbelievable", "massive boost", "crisis", "slams", "humiliating", "outrage", "appalling")
        val foundLoaded = loadedWords.filter { combinedText.contains(it) }
        val l2 = when {
            foundLoaded.isNotEmpty() -> "Sensationalized framing detected. Content uses emotionally loaded vocabulary ('${foundLoaded.take(3).joinToString("', '")}') rather than objective reporting language."
            isSocialAggregator -> "Aggregator Framing: Social post format designed for high engagement. Summarizes external reporting without an original investigative byline."
            else -> "Informational Stance: Objective reporting structure with documented subject focus and low sensationalism."
        }

        // Layer 3: Evidence Density & Cross-Corroboration
        val l3 = if (sources.isNotEmpty()) {
            "High Evidence Density: Cross-examined against ${sources.size} independent sources (${sources.take(3).joinToString(", ") { it.domain }})."
        } else {
            "Local Evidence Density: Extracted directly from active webpage content without external corroboration."
        }

        val whatsMissing = when {
            isOfficialAnnouncement -> "No major missing confirmation. Formally documented by primary institutional or public record."
            sources.size >= 4 -> "Primary institutional documentation or formal agency statement not yet independently published."
            sources.size in 1..3 -> "Independent secondary confirmation from other major newsrooms is currently limited."
            sources.isEmpty() -> "Multi-source external corroboration has not yet cross-verified this report."
            else -> ""
        }

        return CredibilityAssessment(
            score = score,
            verdict = verdict,
            reason = reason,
            isAggregator = isSocialAggregator,
            originalSource = detectedOriginalSource,
            aggregatorSource = aggregatorSource,
            layer1 = l1,
            layer2 = l2,
            layer3 = l3,
            whatsMissing = whatsMissing
        )
    }

    /**
     * Parses the LLM answer into a structured FokkAiAnalysis object.
     */
    private fun parseAnalysisOutput(
        rawOutput: String,
        sources: List<CorroboratedSource>,
        title: String,
        host: String
    ): FokkAiAnalysis {
        val sanitized = sanitizeLlmOutput(rawOutput)
        val splitFollowups = sanitized.split(Regex("(?i)SUGGESTED_FOLLOWUPS:"))
        val mainBody = splitFollowups[0].trim()
        val followUps = if (splitFollowups.size > 1) {
            splitFollowups[1].trim().split(Regex("[|\n]"))
                .map { stripEmojis(it.trim().removePrefix("-").removePrefix("*").trim()) }
                .filter { it.isNotBlank() && it.length > 5 && !it.startsWith("SUGGESTED", ignoreCase = true) }
                .take(3)
        } else {
            listOf(
                "What are the verified primary sources for this story?",
                "What are the latest official developments?"
            )
        }

        // Tag extraction helper
        fun extractTag(tag: String): String {
            val m = Regex("(?is)(?:\\*\\*)?${tag}(?:\\*\\*)?\\s*:\\s*(.*?)(?=(?:\\*\\*)?(?:SCORE|VERDICT|BIAS|LAYER1_DOMAIN|LAYER2_STANCE|LAYER3_EVIDENCE|KEY_EVIDENCE|EXECUTIVE_BRIEF|TRUTH_AUDIT|SUGGESTED_FOLLOWUPS)(?:\\*\\*)?:|$)").find(mainBody)
            return m?.groupValues?.get(1)?.trim().orEmpty()
        }

        val tagExec = extractTag("EXECUTIVE_BRIEF")
        val tagScore = extractTag("SCORE").filter { it.isDigit() }.toIntOrNull()
        val tagVerdict = extractTag("VERDICT")
        val tagBias = extractTag("BIAS")
        val tagL1 = extractTag("LAYER1_DOMAIN")
        val tagL2 = extractTag("LAYER2_STANCE")
        val tagL3 = extractTag("LAYER3_EVIDENCE")

        // Lines and bullets
        val lines = mainBody.split("\n").map { it.trim() }.filter { it.isNotBlank() }
        val bulletPoints = lines
            .filter { (it.startsWith("-") || it.startsWith("*") || it.startsWith("•") || Regex("""^\d+\.""").containsMatchIn(it)) && !it.contains("SUGGESTED_FOLLOWUPS", ignoreCase = true) }
            .map { it.replace(Regex("""^[-*•\d.\s]+"""), "").trim() }
            .filter { it.length > 15 && !it.startsWith("SCORE", ignoreCase = true) && !it.startsWith("VERDICT", ignoreCase = true) }
            .take(4)

        val execBrief = when {
            tagExec.isNotBlank() -> tagExec
            else -> {
                val candidate = lines.firstOrNull { l ->
                    !l.startsWith("#") && !l.startsWith("-") && !l.startsWith("*") &&
                    !l.startsWith("SCORE", ignoreCase = true) && !l.startsWith("VERDICT", ignoreCase = true) &&
                    !l.startsWith("EXECUTIVE", ignoreCase = true) && !l.startsWith("TRUTH_AUDIT", ignoreCase = true) &&
                    l.length > 35
                }
                candidate ?: "Objective multi-source analysis synthesized for $title."
            }
        }

        val assessment = evaluateCredibility(host, title, mainBody, sources, tagScore, tagVerdict)
        val finalBias = if (tagBias.isNotBlank()) tagBias else "Objective / Fact-Focused"
        val finalL1 = if (tagL1.isNotBlank()) tagL1 else assessment.layer1
        val finalL2 = if (tagL2.isNotBlank()) tagL2 else assessment.layer2
        val finalL3 = if (tagL3.isNotBlank()) tagL3 else assessment.layer3

        val tagged = (if (bulletPoints.isNotEmpty()) bulletPoints else listOf(execBrief)).map {
            TaggedEvidencePoint(it, classifyBullet(it))
        }

        return FokkAiAnalysis(
            executiveBrief = execBrief,
            keyEvidencePoints = if (bulletPoints.isNotEmpty()) bulletPoints else listOf(execBrief),
            fullAnalysis = mainBody,
            credibilityScore = assessment.score,
            credibilityVerdict = assessment.verdict,
            credibilityReason = assessment.reason,
            biasTone = finalBias,
            corroboratedSources = sources,
            verifiedClaims = bulletPoints.take(3),
            followUpQuestions = followUps,
            layer1DomainIdentity = finalL1,
            layer2RhetoricalStance = finalL2,
            layer3EvidenceDensity = finalL3,
            originalSource = assessment.originalSource,
            aggregatorSource = assessment.aggregatorSource,
            isAggregator = assessment.isAggregator,
            whatsMissing = assessment.whatsMissing,
            taggedBullets = tagged
        )
    }

    /**
     * Synthesizes an on-device forensic analysis when cloud LLMs are offline.
     */
    fun synthesizeOfflineAnalysis(
        title: String,
        host: String,
        pageContext: String,
        sources: List<CorroboratedSource>
    ): FokkAiAnalysis {
        val sentences = pageContext.split(Regex("[.!?]\\s+"))
            .map { stripEmojis(it.trim()) }
            .filter { it.length > 25 }

        val stats = sentences.filter { s ->
            Regex("""\d+%|\$\d+|\b\d+(?:,\d{3})*(?:\.\d+)?\s*(?:billion|million|trillion|percent|users|shares|times|people|k|m|b)?\b""", RegexOption.IGNORE_CASE).containsMatchIn(s)
        }.take(3)

        val lead = sentences.firstOrNull() ?: "Article records extracted directly from $host."
        val bullets = if (stats.isNotEmpty()) stats else sentences.take(3)
        val tagged = bullets.map { TaggedEvidencePoint(it, classifyBullet(it)) }

        val assessment = evaluateCredibility(host, title, pageContext, sources)

        val sb = StringBuilder()
        sb.append("### ANALYSIS SUMMARY\n")
        sb.append("${assessment.reason}\n\n")

        if (sources.isNotEmpty()) {
            sb.append("### CORROBORATING SOURCES\n")
            sources.forEachIndexed { i, s ->
                sb.append("${i + 1}. **${s.title}** (${s.domain})\n")
                if (s.snippet.isNotBlank()) sb.append("   ${s.snippet}\n")
            }
            sb.append("\n")
        }

        sb.append("### EXECUTIVE SUMMARY\n")
        sb.append("$lead.\n\n")

        sb.append("### KEY EVIDENCE POINTS\n")
        bullets.forEachIndexed { i, b ->
            sb.append("${i + 1}. ${b.trimEnd('.')}.\n")
        }

        return FokkAiAnalysis(
            executiveBrief = lead,
            keyEvidencePoints = bullets,
            fullAnalysis = sb.toString(),
            credibilityScore = assessment.score,
            credibilityVerdict = assessment.verdict,
            credibilityReason = assessment.reason,
            biasTone = "Empirical Neutral",
            corroboratedSources = sources,
            verifiedClaims = bullets.take(3),
            followUpQuestions = listOf(
                "What are the verified primary sources for this story?",
                "What are the latest official developments?"
            ),
            layer1DomainIdentity = assessment.layer1,
            layer2RhetoricalStance = assessment.layer2,
            layer3EvidenceDensity = assessment.layer3,
            originalSource = assessment.originalSource,
            aggregatorSource = assessment.aggregatorSource,
            isAggregator = assessment.isAggregator,
            whatsMissing = assessment.whatsMissing,
            taggedBullets = tagged
        )
    }

    /**
     * Builds structured offline forensic briefing for interactive questions when offline.
     */
    fun buildOfflineForensicSynthesis(
        query: String,
        pageContext: String,
        sources: List<CorroboratedSource>
    ): String {
        val assessment = evaluateCredibility("", "", pageContext, sources)
        val sb = StringBuilder()

        val pubNames = if (sources.isNotEmpty()) {
            sources.take(4).map {
                when {
                    it.domain.contains("guardian") -> "The Guardian"
                    it.domain.contains("times") -> "The Times"
                    it.domain.contains("standard") -> "The Standard"
                    it.domain.contains("independent") -> "The Independent"
                    it.domain.contains("lbc") -> "LBC"
                    it.domain.contains("yahoo") -> "Yahoo"
                    it.domain.contains("sky") -> "Sky News"
                    it.domain.contains("bbc") -> "BBC News"
                    it.domain.contains("athletic") -> "The Athletic"
                    it.domain.contains("reuters") -> "Reuters"
                    else -> it.domain.split(".").firstOrNull()?.replaceFirstChar { c -> c.uppercase() } ?: it.domain
                }
            }.distinct().joinToString(", ")
        } else ""

        val directAnswer = when {
            sources.size >= 2 -> "Credibly documented across major independent newsrooms, including $pubNames."
            sources.size == 1 -> "Reported by ${sources[0].domain}; awaiting broader multi-source corroboration."
            else -> "Based on available active reporting; external independent dispatches are currently limited."
        }

        sb.append(directAnswer)
        sb.append("\n\n")

        if (pageContext.isNotBlank()) {
            val qLower = query.lowercase(Locale.ROOT)
            val sentences = pageContext.split(Regex("[.!?]\\s+"))
                .map { stripEmojis(it.trim()) }
                .filter { it.length > 25 && !it.startsWith("Want to bookmark", ignoreCase = true) }
                .take(100)

            val words = qLower.split(Regex("\\W+")).filter { it.length > 3 && !it.matches(Regex("^(what|this|about|article|explain|tell|page|news)$")) }
            val scored = sentences.map { s ->
                val hits = words.count { s.lowercase(Locale.ROOT).contains(it) }
                Pair(s, hits)
            }.sortedByDescending { it.second }

            val relevant = scored.filter { it.second > 0 }.map { it.first }.take(3)
            val leadSentences = if (relevant.isNotEmpty()) relevant else sentences.take(3)

            leadSentences.forEachIndexed { idx, b ->
                val cleanB = b.replace(Regex("""^[\s•*–—\-\d.)\]]+"""), "").trimEnd('.')
                val citationTag = if (sources.isNotEmpty()) " [${(idx % sources.size) + 1}]" else ""
                sb.append("• $cleanB$citationTag.\n")
            }
            sb.append("\n")
        }

        if (assessment.whatsMissing.isNotBlank() && !assessment.whatsMissing.startsWith("No major")) {
            sb.append("Missing context: ${assessment.whatsMissing}\n")
        }

        sb.append("\nSUGGESTED_FOLLOWUPS: What are the verified primary sources? | What are the latest developments?")
        return sb.toString()
    }

    /**
     * Strict emoji cleaner removing all unicode emoji code points.
     */
    fun stripEmojis(text: String): String {
        if (text.isEmpty()) return ""
        val sb = StringBuilder(text.length)
        var i = 0
        while (i < text.length) {
            val cp = text.codePointAt(i)
            val charCount = Character.charCount(cp)
            val isEmoji = (cp in 0x1F300..0x1FAFF) ||
                    (cp in 0x1F600..0x1F64F) ||
                    (cp in 0x2600..0x27BF) ||
                    (cp in 0xFE00..0xFE0F) ||
                    (cp in 0x1F900..0x1F9FF) ||
                    (cp in 0x1F1E6..0x1F1FF) ||
                    (cp in 0x2300..0x23FF) ||
                    (cp == 0x2B50) || (cp == 0x2B55) || (cp == 0x200D)
            if (!isEmoji) {
                sb.appendCodePoint(cp)
            }
            i += charCount
        }
        return sb.toString().trim()
    }
}
